alter table public.questoes drop constraint if exists questoes_nivel_check;
alter table public.questoes add constraint questoes_nivel_check check (nivel between 0 and 4);

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":2003,"materia":"port","nivel":0,"enunciado":"Qual é o plural correto de “cidadão”?","opcoes":["Cidadãos","Cidadões","Cidadães","Cidadãoes"],"explicacao":"“Cidadão” faz o plural em -ãos, como “irmãos” e “cristãos”."},{"id":2004,"materia":"port","nivel":0,"enunciado":"Qual palavra está escrita corretamente?","opcoes":["Exceção","Excessão","Esceção","Exeção"],"explicacao":"Escreve-se “exceção”, com XC e Ç. A forma com SS é um erro comum."},{"id":2005,"materia":"port","nivel":0,"enunciado":"Complete: “Moro nesta cidade ___ dois anos.”","opcoes":["há","a","à","ah"],"explicacao":"Para indicar tempo já decorrido usa-se o verbo haver: “há dois anos”. Daria para trocar por “faz dois anos”."},{"id":2006,"materia":"port","nivel":0,"enunciado":"Qual é o antônimo de “efêmero”?","opcoes":["Duradouro","Passageiro","Breve","Fugaz"],"explicacao":"Efêmero é o que dura pouco. Passageiro, breve e fugaz são sinônimos; o oposto é duradouro."},{"id":2007,"materia":"port","nivel":0,"enunciado":"Com o Acordo Ortográfico de 2009, qual destas palavras perdeu o acento?","opcoes":["Ideia","Herói","Café","Após"],"explicacao":"Paroxítonas com ditongo aberto “ei” e “oi” perderam o acento (ideia, assembleia, jiboia). Oxítonas como “herói” continuam acentuadas."},{"id":2008,"materia":"port","nivel":0,"enunciado":"Em qual frase o acento grave (crase) está correto?","opcoes":["Vou à escola amanhã.","Fui à pé até o centro.","Começou à chover.","Entreguei o documento à ele."],"explicacao":"Crase é a fusão da preposição “a” com o artigo “a”. Não ocorre antes de palavra masculina (pé), de verbo (chover) ou de pronome pessoal (ele)."},{"id":2009,"materia":"const","nivel":0,"enunciado":"Segundo o art. 1º da Constituição, qual destes é um FUNDAMENTO da República?","opcoes":["Dignidade da pessoa humana","Erradicar a pobreza","Independência nacional","Garantir o desenvolvimento nacional"],"explicacao":"Os fundamentos (art. 1º) são soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo político. Erradicar a pobreza e garantir o desenvolvimento são objetivos (art. 3º); independência nacional é princípio das relações internacionais (art. 4º)."},{"id":2010,"materia":"const","nivel":0,"enunciado":"Quais são os Poderes da União, segundo a Constituição?","opcoes":["Legislativo, Executivo e Judiciário","Executivo, Judiciário e Ministério Público","Legislativo, Executivo e Moderador","Executivo, Legislativo e Tribunal de Contas"],"explicacao":"Art. 2º: são Poderes da União, independentes e harmônicos entre si, o Legislativo, o Executivo e o Judiciário."},{"id":2011,"materia":"const","nivel":0,"enunciado":"Qual a idade mínima para se candidatar a Presidente da República?","opcoes":["35 anos","30 anos","21 anos","40 anos"],"explicacao":"Art. 14, § 3º, VI, “a”: 35 anos para Presidente, Vice e Senador."},{"id":2012,"materia":"const","nivel":0,"enunciado":"Qual é a duração do mandato de um Senador?","opcoes":["8 anos","4 anos","6 anos","5 anos"],"explicacao":"O mandato de Senador é de oito anos, com renovação alternada de um e dois terços a cada quatro anos (art. 46)."},{"id":2013,"materia":"const","nivel":0,"enunciado":"Qual remédio constitucional protege a liberdade de locomoção?","opcoes":["Habeas corpus","Habeas data","Mandado de segurança","Ação popular"],"explicacao":"O habeas corpus é concedido sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção (art. 5º, LXVIII)."},{"id":2014,"materia":"adm","nivel":0,"enunciado":"Qual destes NÃO está entre os princípios expressos no caput do art. 37 da Constituição?","opcoes":["Razoabilidade","Eficiência","Publicidade","Moralidade"],"explicacao":"O caput traz o LIMPE: Legalidade, Impessoalidade, Moralidade, Publicidade e Eficiência. Razoabilidade é princípio implícito na CF."},{"id":2015,"materia":"adm","nivel":0,"enunciado":"Em regra, como se ingressa em cargo público efetivo?","opcoes":["Por aprovação em concurso público","Por nomeação livre do chefe do Executivo","Por indicação política","Por sorteio entre inscritos"],"explicacao":"Art. 37, II: a investidura em cargo ou emprego público depende de aprovação prévia em concurso público, ressalvados os cargos em comissão."},{"id":2016,"materia":"pen","nivel":0,"enunciado":"Subtrair coisa alheia móvel, para si ou para outro, sem violência ou grave ameaça, é crime de:","opcoes":["Furto","Roubo","Apropriação indébita","Estelionato"],"explicacao":"É o furto (art. 155 do CP). Se houver violência ou grave ameaça, vira roubo (art. 157)."},{"id":2017,"materia":"pen","nivel":0,"enunciado":"A partir de qual idade a pessoa é penalmente imputável no Brasil?","opcoes":["18 anos","16 anos","21 anos","14 anos"],"explicacao":"Art. 27 do CP e art. 228 da CF: menores de 18 anos são penalmente inimputáveis e ficam sujeitos à legislação especial (ECA)."},{"id":2018,"materia":"pen","nivel":0,"enunciado":"Obter vantagem ilícita induzindo ou mantendo alguém em erro, mediante fraude, é crime de:","opcoes":["Estelionato","Furto","Extorsão","Receptação"],"explicacao":"É a definição do estelionato, no art. 171 do Código Penal."},{"id":2019,"materia":"pen","nivel":0,"enunciado":"O crime descrito simplesmente como “matar alguém” é o:","opcoes":["Homicídio","Latrocínio","Infanticídio","Feminicídio"],"explicacao":"“Matar alguém” é o tipo do homicídio simples, art. 121 do CP."},{"id":2020,"materia":"ppen","nivel":0,"enunciado":"Quem preside o inquérito policial?","opcoes":["O delegado de polícia","O juiz","O promotor de justiça","O defensor público"],"explicacao":"O inquérito é conduzido pela autoridade policial, ou seja, o delegado de polícia."},{"id":2021,"materia":"inf","nivel":0,"enunciado":"No Windows, o atalho Ctrl + C serve para:","opcoes":["Copiar","Colar","Recortar","Desfazer"],"explicacao":"Ctrl+C copia, Ctrl+V cola, Ctrl+X recorta e Ctrl+Z desfaz."},{"id":2022,"materia":"inf","nivel":0,"enunciado":"Qual destes é um navegador de internet?","opcoes":["Google Chrome","Microsoft Excel","Windows","Outlook"],"explicacao":"Chrome é navegador. Excel é planilha, Windows é sistema operacional e Outlook é cliente de e-mail."},{"id":2023,"materia":"inf","nivel":0,"enunciado":"No Excel, uma fórmula deve começar com qual caractere?","opcoes":["=","#","@","&"],"explicacao":"Toda fórmula no Excel começa com o sinal de igual. Ex.: =SOMA(A1:A5)."},{"id":2024,"materia":"inf","nivel":0,"enunciado":"O que é phishing?","opcoes":["Golpe para roubar dados com sites falsos","Vírus que apaga o disco rígido inteiro","Programa que acelera a conexão","Cópia de segurança dos arquivos"],"explicacao":"Phishing é a “pescaria” de dados: o golpista se passa por banco, órgão público ou empresa para roubar senhas e informações."},{"id":2025,"materia":"inf","nivel":0,"enunciado":"Qual destes é um periférico de ENTRADA?","opcoes":["Teclado","Monitor","Impressora","Caixa de som"],"explicacao":"Teclado envia dados ao computador. Monitor, impressora e caixa de som são de saída."},{"id":2026,"materia":"rl","nivel":0,"enunciado":"Qual o próximo número da sequência 2, 4, 8, 16, …?","opcoes":["32","24","30","20"],"explicacao":"Cada termo é o dobro do anterior: 16 × 2 = 32."},{"id":2027,"materia":"rl","nivel":0,"enunciado":"Quanto é 25% de 80?","opcoes":["20","25","16","40"],"explicacao":"25% é um quarto: 80 ÷ 4 = 20."},{"id":2028,"materia":"rl","nivel":0,"enunciado":"Se hoje é sábado, depois de amanhã será:","opcoes":["Segunda-feira","Domingo","Terça-feira","Sexta-feira"],"explicacao":"Amanhã é domingo; depois de amanhã, segunda-feira."},{"id":2029,"materia":"rl","nivel":0,"enunciado":"Um produto de R$ 200,00 recebeu 15% de desconto. Qual o novo preço?","opcoes":["R$ 170,00","R$ 185,00","R$ 150,00","R$ 175,00"],"explicacao":"15% de 200 é 30. Então 200 − 30 = 170."},{"id":2030,"materia":"dh","nivel":0,"enunciado":"Em que ano a ONU adotou a Declaração Universal dos Direitos Humanos?","opcoes":["1948","1945","1988","1966"],"explicacao":"A DUDH foi adotada pela Assembleia Geral da ONU em 10 de dezembro de 1948. A ONU foi criada em 1945."},{"id":2031,"materia":"dh","nivel":0,"enunciado":"Qual é o número da Lei Maria da Penha?","opcoes":["Lei nº 11.340/2006","Lei nº 8.069/1990","Lei nº 9.099/1995","Lei nº 10.826/2003"],"explicacao":"Lei Maria da Penha: 11.340/2006. A 8.069/90 é o ECA, a 9.099/95 trata dos Juizados Especiais e a 10.826/03 é o Estatuto do Desarmamento."},{"id":2032,"materia":"port","nivel":0,"enunciado":"Qual é um sinônimo de “célere”?","opcoes":["Rápido","Lento","Claro","Caro"],"explicacao":"Célere significa veloz, ágil. Fala-se em “processo célere”."},{"id":2033,"materia":"port","nivel":0,"enunciado":"Qual destas palavras é oxítona?","opcoes":["Café","Árvore","Lápis","Janela"],"explicacao":"Oxítona tem a última sílaba tônica: ca-FÉ. Árvore é proparoxítona; lápis e janela são paroxítonas."},{"id":2034,"materia":"port","nivel":0,"enunciado":"Complete: “Estudei muito, ___ não passei.”","opcoes":["mas","mais","más","mau"],"explicacao":"“Mas” é conjunção adversativa, com ideia de oposição. “Mais” indica quantidade."},{"id":2035,"materia":"port","nivel":0,"enunciado":"Qual palavra está escrita corretamente?","opcoes":["Paralisar","Paralizar","Paraliçar","Paralissar"],"explicacao":"Paralisar se escreve com S porque vem de “paralisia”."},{"id":2036,"materia":"const","nivel":0,"enunciado":"Em que ano foi promulgada a Constituição Federal em vigor?","opcoes":["1988","1967","1946","1998"],"explicacao":"A Constituição Cidadã foi promulgada em 5 de outubro de 1988."},{"id":2037,"materia":"const","nivel":0,"enunciado":"Qual é a duração do mandato do Presidente da República?","opcoes":["4 anos","5 anos","6 anos","8 anos"],"explicacao":"Art. 82: mandato de quatro anos, permitida uma reeleição para o período seguinte."},{"id":2038,"materia":"const","nivel":0,"enunciado":"Para quem o voto é FACULTATIVO, segundo a Constituição?","opcoes":["Maiores de 16 e menores de 18 anos","Maiores de 60 anos","Servidores públicos","Maiores de 18 e menores de 21 anos"],"explicacao":"Art. 14, § 1º, II: é facultativo para analfabetos, maiores de 70 anos e maiores de 16 e menores de 18 anos."},{"id":2039,"materia":"adm","nivel":0,"enunciado":"Um ato administrativo ilegal deve ser:","opcoes":["Anulado","Revogado","Mantido até o fim do mandato","Convertido em lei"],"explicacao":"Ato ilegal é anulado. A revogação é para atos válidos que deixaram de ser convenientes."},{"id":2040,"materia":"adm","nivel":0,"enunciado":"O cargo em comissão é de:","opcoes":["Livre nomeação e exoneração","Provimento exclusivo por concurso","Vitaliciedade garantida","Estabilidade após 3 anos"],"explicacao":"Art. 37, II, da CF: cargos em comissão são declarados em lei de livre nomeação e exoneração."},{"id":2041,"materia":"pen","nivel":0,"enunciado":"Adquirir ou receber coisa que sabe ser produto de crime é:","opcoes":["Receptação","Furto","Estelionato","Favorecimento pessoal"],"explicacao":"É a receptação, prevista no art. 180 do Código Penal."},{"id":2042,"materia":"ppen","nivel":0,"enunciado":"Qual peça dá início à ação penal pública?","opcoes":["Denúncia","Queixa-crime","Boletim de ocorrência","Relatório do inquérito"],"explicacao":"Na ação pública, o MP oferece denúncia. Na privada, o ofendido oferece queixa-crime."},{"id":2043,"materia":"ppen","nivel":0,"enunciado":"Quem é o titular da ação penal pública?","opcoes":["O Ministério Público","O delegado de polícia","A vítima","O juiz"],"explicacao":"Art. 129, I, da Constituição: promover privativamente a ação penal pública é função do MP."},{"id":2044,"materia":"leg","nivel":0,"enunciado":"A Lei nº 11.343/2006 é conhecida como:","opcoes":["Lei de Drogas","Lei Maria da Penha","Estatuto do Desarmamento","Lei dos Crimes Hediondos"],"explicacao":"A 11.343/2006 instituiu o Sistema Nacional de Políticas Públicas sobre Drogas."},{"id":2045,"materia":"leg","nivel":0,"enunciado":"Qual é o número do Estatuto do Desarmamento?","opcoes":["Lei nº 10.826/2003","Lei nº 8.072/1990","Lei nº 9.455/1997","Lei nº 12.850/2013"],"explicacao":"Estatuto do Desarmamento: 10.826/2003. As outras são Crimes Hediondos, Tortura e Organizações Criminosas."},{"id":2046,"materia":"leg","nivel":0,"enunciado":"A Lei nº 8.072/1990 trata dos:","opcoes":["Crimes hediondos","Juizados especiais","Crimes de tortura","Crimes de trânsito"],"explicacao":"É a Lei dos Crimes Hediondos."},{"id":2047,"materia":"inf","nivel":0,"enunciado":"Qual destas unidades de armazenamento é a MAIOR?","opcoes":["Terabyte","Gigabyte","Megabyte","Kilobyte"],"explicacao":"A ordem crescente é KB, MB, GB e TB. Cada uma tem cerca de mil vezes a anterior."},{"id":2048,"materia":"inf","nivel":0,"enunciado":"No Windows, o atalho Ctrl + Z serve para:","opcoes":["Desfazer a última ação","Fechar o programa","Salvar o arquivo","Selecionar tudo"],"explicacao":"Ctrl+Z desfaz a última ação na maioria dos programas, e Ctrl+Y refaz."},{"id":2049,"materia":"inf","nivel":0,"enunciado":"Um arquivo com extensão .xlsx é, normalmente:","opcoes":["Uma planilha do Excel","Um documento do Word","Uma apresentação do PowerPoint","Uma imagem"],"explicacao":"xlsx é planilha, docx é documento e pptx é apresentação."},{"id":2050,"materia":"rl","nivel":0,"enunciado":"Qual o próximo número da sequência 3, 6, 9, 12, …?","opcoes":["15","14","16","18"],"explicacao":"A sequência soma 3 a cada termo: 12 + 3 = 15."},{"id":2051,"materia":"rl","nivel":0,"enunciado":"Quanto é a metade de um terço de 90?","opcoes":["15","30","45","20"],"explicacao":"Um terço de 90 é 30; a metade de 30 é 15."},{"id":2052,"materia":"rl","nivel":0,"enunciado":"Todo policial é servidor. João é policial. Logo:","opcoes":["João é servidor","Todo servidor é policial","João não é servidor","Nada se pode concluir"],"explicacao":"Se todo policial está no grupo dos servidores e João é policial, João também está nesse grupo."},{"id":2053,"materia":"dh","nivel":0,"enunciado":"Segundo o ECA, criança é a pessoa com idade até:","opcoes":["12 anos incompletos","14 anos incompletos","10 anos completos","18 anos incompletos"],"explicacao":"Art. 2º do ECA. Adolescente é quem tem entre 12 e 18 anos."},{"id":2054,"materia":"dh","nivel":0,"enunciado":"Segundo o Estatuto da Pessoa Idosa, é idosa a pessoa com idade igual ou superior a:","opcoes":["60 anos","65 anos","70 anos","55 anos"],"explicacao":"Art. 1º da Lei 10.741/2003."},{"id":2055,"materia":"port","nivel":0,"enunciado":"Qual é o plural correto de “pão”?","opcoes":["Pães","Pãos","Pãoes","Pões"],"explicacao":"“Pão” faz o plural em -ães, como “cães” e “alemães”."},{"id":2056,"materia":"port","nivel":0,"enunciado":"Qual é o antônimo de “escasso”?","opcoes":["Abundante","Raro","Pouco","Insuficiente"],"explicacao":"Escasso é o que existe em pouca quantidade. O oposto é abundante."},{"id":2057,"materia":"port","nivel":0,"enunciado":"Qual destas palavras é proparoxítona?","opcoes":["Público","Prova","Concurso","Juiz"],"explicacao":"Proparoxítona tem a antepenúltima sílaba tônica: PÚ-bli-co. Todas as proparoxítonas são acentuadas."},{"id":2058,"materia":"port","nivel":0,"enunciado":"Qual palavra está escrita corretamente?","opcoes":["Beneficente","Beneficiente","Benificente","Beneficênte"],"explicacao":"O certo é “beneficente”, sem o “i” depois do “c”."},{"id":2059,"materia":"const","nivel":0,"enunciado":"Quem chefia o Poder Executivo federal?","opcoes":["O Presidente da República","O Presidente do Senado","O Presidente do STF","O Ministro da Justiça"],"explicacao":"Art. 76: o Executivo é exercido pelo Presidente, auxiliado pelos Ministros de Estado."},{"id":2060,"materia":"const","nivel":0,"enunciado":"A Câmara dos Deputados é composta de representantes:","opcoes":["Do povo","Dos estados","Dos municípios","Dos partidos"],"explicacao":"Art. 45. Já o Senado representa os estados e o DF (art. 46)."},{"id":2061,"materia":"const","nivel":0,"enunciado":"Qual é a duração do mandato de um deputado federal?","opcoes":["4 anos","8 anos","5 anos","6 anos"],"explicacao":"A legislatura tem quatro anos (art. 44, parágrafo único)."},{"id":2062,"materia":"const","nivel":0,"enunciado":"Qual destes é um OBJETIVO fundamental da República (art. 3º)?","opcoes":["Erradicar a pobreza e a marginalização","Prevalência dos direitos humanos","Dignidade da pessoa humana","Independência nacional"],"explicacao":"Erradicar a pobreza é objetivo (art. 3º, III). Dignidade da pessoa humana é fundamento (art. 1º); prevalência dos direitos humanos e independência nacional são princípios das relações internacionais (art. 4º)."},{"id":2063,"materia":"adm","nivel":0,"enunciado":"Qual princípio obriga a Administração a agir somente conforme a lei?","opcoes":["Legalidade","Publicidade","Eficiência","Moralidade"],"explicacao":"Para o particular, vale fazer o que a lei não proíbe. Para a Administração, só o que a lei permite."},{"id":2064,"materia":"adm","nivel":0,"enunciado":"Qual destes integra a Administração INDIRETA?","opcoes":["Autarquia","Ministério","Secretaria estadual","Presidência da República"],"explicacao":"A indireta reúne autarquias, fundações públicas, empresas públicas e sociedades de economia mista. Ministérios e secretarias são órgãos da direta."},{"id":2065,"materia":"adm","nivel":0,"enunciado":"O princípio da publicidade exige que os atos administrativos sejam:","opcoes":["Divulgados oficialmente","Aprovados pelo Judiciário","Assinados por dois servidores","Mantidos em sigilo"],"explicacao":"A regra é a transparência. O sigilo é exceção prevista em lei."},{"id":2066,"materia":"adm","nivel":0,"enunciado":"A publicidade oficial NÃO pode conter:","opcoes":["Nomes ou imagens de promoção pessoal de autoridades","Informações de utilidade pública à população","Conteúdo de caráter educativo ou informativo","Orientação social sobre serviços públicos"],"explicacao":"Art. 37, § 1º, ligado ao princípio da impessoalidade."},{"id":2067,"materia":"pen","nivel":0,"enunciado":"Ofender a integridade corporal ou a saúde de outra pessoa é crime de:","opcoes":["Lesão corporal","Ameaça","Injúria","Constrangimento ilegal"],"explicacao":"Art. 129 do Código Penal."},{"id":2068,"materia":"pen","nivel":0,"enunciado":"Privar alguém de sua liberdade, mantendo-o preso em um local, é crime de:","opcoes":["Sequestro e cárcere privado","Extorsão mediante sequestro","Ameaça qualificada","Furto de uso"],"explicacao":"Art. 148 do CP. Se o objetivo for obter resgate, vira extorsão mediante sequestro (art. 159)."},{"id":2069,"materia":"pen","nivel":0,"enunciado":"Destruir, inutilizar ou deteriorar coisa alheia é crime de:","opcoes":["Dano","Furto","Roubo","Apropriação indébita"],"explicacao":"Art. 163 do Código Penal."},{"id":2070,"materia":"pen","nivel":0,"enunciado":"“Não há crime sem lei anterior que o defina” expressa o princípio da:","opcoes":["Legalidade","Insignificância","Proporcionalidade","Culpabilidade"],"explicacao":"Art. 1º do CP e art. 5º, XXXIX, da CF. Envolve a reserva legal e a anterioridade da lei penal."},{"id":2071,"materia":"ppen","nivel":0,"enunciado":"Qual documento formaliza a prisão em flagrante?","opcoes":["Auto de prisão em flagrante","Mandado de prisão","Termo circunstanciado","Denúncia"],"explicacao":"Lavrado pela autoridade policial, com oitiva do condutor, das testemunhas e do preso."},{"id":2072,"materia":"ppen","nivel":0,"enunciado":"Ao concluir o inquérito, a autoridade policial elabora um:","opcoes":["Relatório","Despacho de denúncia","Sentença","Parecer do Ministério Público"],"explicacao":"Art. 10, § 1º, do CPP. O relatório é enviado ao juiz competente."},{"id":2073,"materia":"ppen","nivel":0,"enunciado":"O inquérito policial é um procedimento:","opcoes":["Administrativo e investigativo","Judicial e contraditório","Legislativo","Recursal"],"explicacao":"Serve para reunir elementos sobre autoria e materialidade do crime."},{"id":2074,"materia":"ppen","nivel":0,"enunciado":"A prisão de qualquer pessoa deve ser comunicada imediatamente ao juiz, ao Ministério Público e:","opcoes":["À família do preso ou pessoa por ele indicada","Ao empregador do preso, por escrito","Ao prefeito do município da prisão","À imprensa local, para transparência"],"explicacao":"Art. 306 do CPP e art. 5º, LXII, da CF."},{"id":2075,"materia":"leg","nivel":0,"enunciado":"A Lei Maria da Penha protege:","opcoes":["A mulher em situação de violência doméstica","Crianças e adolescentes em situação de risco","Pessoas idosas em situação de abandono","Consumidores lesados em relações de compra"],"explicacao":"Lei 11.340/2006."},{"id":2076,"materia":"leg","nivel":0,"enunciado":"Qual é o número da lei do Estatuto da Criança e do Adolescente?","opcoes":["Lei nº 8.069/1990","Lei nº 10.741/2003","Lei nº 11.340/2006","Lei nº 8.072/1990"],"explicacao":"A 10.741/2003 é o Estatuto da Pessoa Idosa."},{"id":2077,"materia":"leg","nivel":0,"enunciado":"A Lei nº 9.099/1995 criou os:","opcoes":["Juizados Especiais Cíveis e Criminais","Tribunais do Júri estaduais","Conselhos Tutelares municipais","Tribunais de Contas dos Municípios"],"explicacao":"Eles julgam infrações de menor potencial ofensivo com rito mais simples."},{"id":2078,"materia":"leg","nivel":0,"enunciado":"A Lei nº 9.455/1997 define os crimes de:","opcoes":["Tortura","Lavagem de dinheiro","Abuso de autoridade","Trânsito"],"explicacao":"É a Lei de Tortura."},{"id":2079,"materia":"inf","nivel":0,"enunciado":"No Windows, o atalho Ctrl + V serve para:","opcoes":["Colar","Copiar","Recortar","Salvar"],"explicacao":"Ctrl+C copia, Ctrl+X recorta e Ctrl+V cola."},{"id":2080,"materia":"inf","nivel":0,"enunciado":"Na maioria dos programas, Ctrl + P serve para:","opcoes":["Imprimir","Pesquisar","Salvar","Colar"],"explicacao":"P de print."},{"id":2081,"materia":"inf","nivel":0,"enunciado":"Qual destes é um sistema operacional?","opcoes":["Windows","Word","Chrome","Excel"],"explicacao":"Word e Excel são aplicativos; Chrome é navegador."},{"id":2082,"materia":"inf","nivel":0,"enunciado":"Um arquivo com extensão .docx é, normalmente:","opcoes":["Um documento do Word","Uma planilha","Uma apresentação","Um vídeo"],"explicacao":"docx é Word, xlsx é Excel e pptx é PowerPoint."},{"id":2083,"materia":"rl","nivel":0,"enunciado":"Qual o próximo número da sequência 1, 4, 9, 16, …?","opcoes":["25","20","24","32"],"explicacao":"São os quadrados perfeitos: 1², 2², 3², 4², 5² = 25."},{"id":2084,"materia":"rl","nivel":0,"enunciado":"Quanto é 10% de 350?","opcoes":["35","3,5","350","70"],"explicacao":"10% é dividir por 10."},{"id":2085,"materia":"rl","nivel":0,"enunciado":"Se 5 canetas custam R$ 10,00, quanto custam 8 canetas?","opcoes":["R$ 16,00","R$ 18,00","R$ 15,00","R$ 20,00"],"explicacao":"Cada caneta custa R$ 2,00. 8 × 2 = 16."},{"id":2086,"materia":"rl","nivel":0,"enunciado":"Quanto é o dobro de 7 somado a 3?","opcoes":["17","20","13","24"],"explicacao":"2 × 7 = 14; 14 + 3 = 17."},{"id":2087,"materia":"dh","nivel":0,"enunciado":"Qual é uma característica dos direitos humanos?","opcoes":["Universalidade","Transferibilidade","Renunciabilidade","Prescritibilidade"],"explicacao":"São universais, indivisíveis, inalienáveis, irrenunciáveis e imprescritíveis."},{"id":2088,"materia":"dh","nivel":0,"enunciado":"Qual organização foi criada em 1945 para promover a paz e os direitos humanos?","opcoes":["ONU","OTAN","OEA","Mercosul"],"explicacao":"A Organização das Nações Unidas nasceu com a Carta de São Francisco, ao fim da Segunda Guerra."},{"id":2089,"materia":"dh","nivel":0,"enunciado":"Segundo a Constituição, a tortura e o tratamento desumano ou degradante são:","opcoes":["Proibidos","Permitidos em investigações graves","Permitidos em estado de defesa","Permitidos por ordem judicial"],"explicacao":"Art. 5º, III."},{"id":2090,"materia":"dh","nivel":0,"enunciado":"Os direitos de primeira dimensão (geração) correspondem às:","opcoes":["Liberdades civis e políticas","Garantias sociais e trabalhistas","Proteções ambientais","Garantias digitais"],"explicacao":"Ligados ao valor da liberdade, limitam o poder do Estado."},{"id":2091,"materia":"dh","nivel":0,"enunciado":"Em que data se comemora o Dia Internacional dos Direitos Humanos?","opcoes":["10 de dezembro","5 de outubro","21 de abril","1º de maio"],"explicacao":"É a data de adoção da Declaração Universal, em 1948."},{"id":2092,"materia":"dh","nivel":0,"enunciado":"Segundo o art. 5º, I, da Constituição, homens e mulheres são iguais em:","opcoes":["Direitos e obrigações","Apenas direitos políticos","Apenas deveres","Apenas direitos trabalhistas"],"explicacao":"A igualdade é plena, nos termos da Constituição."},{"id":2093,"materia":"dh","nivel":0,"enunciado":"Qual direito o caput do art. 5º garante expressamente?","opcoes":["Inviolabilidade do direito à vida","Direito ao lazer","Direito ao trabalho","Direito à moradia"],"explicacao":"O caput garante vida, liberdade, igualdade, segurança e propriedade. Lazer, trabalho e moradia são direitos sociais (art. 6º)."},{"id":2094,"materia":"dh","nivel":0,"enunciado":"Segundo a Constituição, ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de:","opcoes":["Lei","Decreto","Ordem policial","Costume local"],"explicacao":"Art. 5º, II: princípio da legalidade."},{"id":2095,"materia":"leg","nivel":0,"enunciado":"Nas infrações de menor potencial ofensivo, a autoridade policial lavra:","opcoes":["Termo circunstanciado","Auto de prisão em flagrante, sempre","Mandado de prisão","Sentença"],"explicacao":"Art. 69 da Lei 9.099/95."},{"id":2096,"materia":"leg","nivel":0,"enunciado":"Pela Lei Maria da Penha, a violência doméstica pode ser praticada:","opcoes":["Na unidade doméstica, na família ou em relação íntima de afeto","Apenas pelo marido ou companheiro da vítima","Apenas por quem mora na mesma casa da vítima","Apenas por homens, contra mulheres casadas"],"explicacao":"Art. 5º da Lei 11.340/2006."},{"id":2097,"materia":"leg","nivel":0,"enunciado":"Pelo ECA, as medidas socioeducativas se aplicam a:","opcoes":["Adolescentes","Crianças","Adultos","Idosos"],"explicacao":"Criança que pratica ato infracional recebe medidas de proteção (art. 105)."},{"id":2098,"materia":"leg","nivel":0,"enunciado":"Pelo Estatuto do Desarmamento, o certificado de registro de arma autoriza o proprietário a:","opcoes":["Mantê-la em casa ou no trabalho, se for o responsável","Andar armado em qualquer lugar público","Vender a arma sem comunicar à autoridade","Emprestá-la a terceiros de sua confiança"],"explicacao":"Registro é posse. Andar com a arma exige porte."},{"id":2099,"materia":"port","nivel":0,"enunciado":"Quantas sílabas tem a palavra “delegacia”?","opcoes":["5","4","3","6"],"explicacao":"De-le-ga-ci-a. O encontro “ia” no fim forma hiato."},{"id":2100,"materia":"port","nivel":0,"enunciado":"Qual é o feminino de “réu”?","opcoes":["Ré","Réa","Réua","Rea"],"explicacao":"Réu e ré, como em “a ré foi absolvida”."},{"id":2101,"materia":"port","nivel":0,"enunciado":"Qual é o coletivo de lobos?","opcoes":["Alcateia","Matilha","Cardume","Manada"],"explicacao":"Matilha é de cães, cardume é de peixes e manada é de bois ou elefantes."},{"id":2102,"materia":"const","nivel":0,"enunciado":"O Congresso Nacional é composto por:","opcoes":["Câmara dos Deputados e Senado Federal","Senado e STF","Câmara e Tribunal de Contas","Câmara, Senado e Presidência"],"explicacao":"Art. 44."},{"id":2103,"materia":"const","nivel":0,"enunciado":"Quem chefia o Poder Executivo estadual?","opcoes":["O Governador","O Presidente da Assembleia","O Prefeito da capital","O Presidente do Tribunal de Justiça"],"explicacao":"Art. 28."},{"id":2104,"materia":"const","nivel":0,"enunciado":"Qual é o idioma oficial da República Federativa do Brasil?","opcoes":["Língua portuguesa","Português e espanhol","Português e tupi","Não há idioma oficial"],"explicacao":"Art. 13 da Constituição."},{"id":2105,"materia":"adm","nivel":0,"enunciado":"Ao fazer uma licitação, a Administração busca selecionar:","opcoes":["A proposta mais vantajosa","A empresa mais antiga","Sempre a de maior preço","A empresa indicada pelo gestor"],"explicacao":"A licitação também garante isonomia entre os concorrentes."},{"id":2106,"materia":"adm","nivel":0,"enunciado":"Em regra, a desapropriação exige:","opcoes":["Justa e prévia indenização em dinheiro","Indenização em títulos, sempre","Nenhuma indenização","Indenização depois de 10 anos"],"explicacao":"Art. 5º, XXIV. Há exceções, como na reforma agrária, paga em títulos."},{"id":2107,"materia":"adm","nivel":0,"enunciado":"Em regra, os bens públicos são:","opcoes":["Impenhoráveis","Penhoráveis por qualquer credor","Sujeitos a usucapião","De livre venda pelo servidor"],"explicacao":"Por isso as dívidas judiciais do Estado são pagas por precatório."},{"id":2108,"materia":"adm","nivel":0,"enunciado":"O servidor que pratica ato fora das suas atribuições legais comete vício de:","opcoes":["Competência","Finalidade","Objeto","Motivo"],"explicacao":"É o chamado excesso de poder."},{"id":2109,"materia":"pen","nivel":0,"enunciado":"Deixar de prestar assistência a pessoa ferida, quando possível sem risco pessoal, é crime de:","opcoes":["Omissão de socorro","Abandono de incapaz","Lesão corporal","Maus-tratos"],"explicacao":"Art. 135 do Código Penal."},{"id":2110,"materia":"pen","nivel":0,"enunciado":"Entrar ou permanecer em casa alheia contra a vontade do morador é crime de:","opcoes":["Violação de domicílio","Dano","Furto","Esbulho"],"explicacao":"Art. 150 do Código Penal."},{"id":2111,"materia":"pen","nivel":0,"enunciado":"Falsificar, no todo ou em parte, uma carteira de identidade é crime de:","opcoes":["Falsificação de documento público","Estelionato","Falsa identidade","Falsidade ideológica"],"explicacao":"Art. 297 do CP. Falsidade ideológica é inserir informação falsa em documento verdadeiro; falsa identidade é atribuir-se identidade falsa."},{"id":2112,"materia":"ppen","nivel":0,"enunciado":"Na ação penal privada, quem apresenta a acusação é chamado de:","opcoes":["Querelante","Denunciante","Requerido","Assistente"],"explicacao":"O acusado, nesse caso, é o querelado."},{"id":2113,"materia":"ppen","nivel":0,"enunciado":"Na ação penal privada, o acusado é chamado de:","opcoes":["Querelado","Indiciado","Denunciado","Requerente"],"explicacao":"Quem acusa é o querelante."},{"id":2114,"materia":"ppen","nivel":0,"enunciado":"O indiciamento é ato privativo do:","opcoes":["Delegado de polícia","Promotor de justiça","Juiz","Escrivão"],"explicacao":"Art. 2º, § 6º, da Lei 12.830/2013."},{"id":2115,"materia":"ppen","nivel":0,"enunciado":"O boletim de ocorrência serve para:","opcoes":["Registrar a notícia de um fato à polícia","Condenar o suspeito","Arquivar o caso","Expedir mandado de prisão"],"explicacao":"É o registro inicial que pode levar à investigação."},{"id":2116,"materia":"inf","nivel":0,"enunciado":"No Microsoft Word em português, o atalho Ctrl + B serve para:","opcoes":["Salvar","Aplicar negrito","Buscar uma palavra","Abrir um arquivo"],"explicacao":"No Word em português: Ctrl+B salva, Ctrl+N aplica negrito, Ctrl+S sublinha e Ctrl+I aplica itálico. Em programas em inglês, salvar é Ctrl+S."},{"id":2117,"materia":"inf","nivel":0,"enunciado":"No Windows, a Lixeira guarda:","opcoes":["Arquivos excluídos, temporariamente","Arquivos baixados","Programas instalados","Senhas salvas"],"explicacao":"Dá para restaurar os arquivos enquanto ela não é esvaziada."},{"id":2118,"materia":"inf","nivel":0,"enunciado":"Qual destes é um dispositivo de SAÍDA?","opcoes":["Impressora","Mouse","Teclado","Scanner"],"explicacao":"Mouse, teclado e scanner enviam dados ao computador; são de entrada."},{"id":2119,"materia":"rl","nivel":0,"enunciado":"Quanto é 1/2 + 1/4?","opcoes":["3/4","2/6","1/6","2/4"],"explicacao":"1/2 = 2/4. Então 2/4 + 1/4 = 3/4."},{"id":2120,"materia":"rl","nivel":0,"enunciado":"Qual o próximo número da sequência 5, 10, 20, 40, …?","opcoes":["80","60","50","45"],"explicacao":"Cada termo é o dobro do anterior."},{"id":2121,"materia":"rl","nivel":0,"enunciado":"Quanto é 30% de 200?","opcoes":["60","30","70","600"],"explicacao":"10% de 200 é 20. Então 30% é 60."},{"id":2122,"materia":"port","nivel":0,"enunciado":"Qual palavra está escrita corretamente?","opcoes":["Privilégio","Previlégio","Privilégeo","Previlêgio"],"explicacao":"Escreve-se “privilégio”, com i na primeira sílaba e acento na paroxítona terminada em ditongo."},{"id":2123,"materia":"port","nivel":0,"enunciado":"Qual é o antônimo de “lícito”?","opcoes":["Ilícito","Legal","Permitido","Correto"],"explicacao":"Lícito é o que a lei permite. O oposto é ilícito."},{"id":2124,"materia":"port","nivel":0,"enunciado":"Qual palavra está escrita corretamente?","opcoes":["Enxaguar","Enchaguar","Inxaguar","Enxagar"],"explicacao":"Depois de “en” inicial usa-se X: enxaguar, enxame, enxergar."},{"id":2125,"materia":"const","nivel":0,"enunciado":"Qual é a Capital Federal?","opcoes":["Brasília","Rio de Janeiro","São Paulo","Salvador"],"explicacao":"Art. 18, § 1º, da Constituição."},{"id":2126,"materia":"const","nivel":0,"enunciado":"Quantos estados-membros tem a Federação brasileira?","opcoes":["26","27","25","28"],"explicacao":"São 26 estados mais o Distrito Federal, que totalizam 27 unidades federativas."},{"id":2127,"materia":"const","nivel":0,"enunciado":"A Constituição Federal pode ser alterada por meio de:","opcoes":["Emenda constitucional","Lei ordinária","Decreto presidencial","Medida provisória"],"explicacao":"Art. 60."},{"id":2128,"materia":"adm","nivel":0,"enunciado":"O princípio que proíbe favorecer ou perseguir pessoas, exigindo tratamento igual a todos, é o da:","opcoes":["Impessoalidade","Eficiência","Publicidade","Autotutela"],"explicacao":"A Administração age em nome do interesse público, não de interesses pessoais."},{"id":2129,"materia":"adm","nivel":0,"enunciado":"Uma autarquia tem personalidade jurídica de direito:","opcoes":["Público","Privado","Internacional","Misto"],"explicacao":"Empresas públicas e sociedades de economia mista são de direito privado."},{"id":2130,"materia":"adm","nivel":0,"enunciado":"O princípio da eficiência exige que a Administração busque:","opcoes":["Os melhores resultados com uso racional dos recursos","Gastar todo o orçamento","Agir apenas quando provocada","Dar prioridade a interesses particulares"],"explicacao":"Foi incluído no art. 37 pela EC 19/1998."},{"id":2131,"materia":"pen","nivel":0,"enunciado":"Ameaçar alguém, por palavra ou gesto, de causar-lhe mal injusto e grave é crime de:","opcoes":["Ameaça","Injúria","Constrangimento ilegal","Extorsão"],"explicacao":"Art. 147 do Código Penal."},{"id":2132,"materia":"pen","nivel":0,"enunciado":"Causar incêndio, expondo a perigo a vida ou o patrimônio de outrem, é crime de:","opcoes":["Incêndio","Dano","Explosão","Homicídio"],"explicacao":"Art. 250 do CP. É crime de perigo comum."},{"id":2133,"materia":"pen","nivel":0,"enunciado":"Atribuir-se falsa identidade para obter vantagem ou causar dano é crime de:","opcoes":["Falsa identidade","Falsificação de documento público","Estelionato","Falso testemunho"],"explicacao":"Art. 307 do Código Penal."},{"id":2134,"materia":"ppen","nivel":0,"enunciado":"Nos crimes de ação privada, o inquérito policial só pode ser instaurado a requerimento:","opcoes":["De quem pode ajuizar a ação, como o ofendido","Do juiz, de ofício","De qualquer pessoa do povo","Do Ministério Público, sempre"],"explicacao":"Art. 5º, § 5º, do CPP."},{"id":2135,"materia":"ppen","nivel":0,"enunciado":"A prisão em flagrante pode ser feita:","opcoes":["A qualquer hora do dia ou da noite","Apenas durante o dia","Apenas com mandado","Apenas em dias úteis"],"explicacao":"O flagrante não depende de mandado nem de horário."},{"id":2136,"materia":"ppen","nivel":0,"enunciado":"No processo penal, quem interroga o acusado em juízo?","opcoes":["O juiz","O delegado","O escrivão","O oficial de justiça"],"explicacao":"O interrogatório judicial é feito pelo juiz, com perguntas complementares das partes."},{"id":2137,"materia":"leg","nivel":0,"enunciado":"Qual é a lei do Estatuto da Pessoa Idosa?","opcoes":["Lei nº 10.741/2003","Lei nº 8.069/1990","Lei nº 13.146/2015","Lei nº 11.340/2006"],"explicacao":"A 13.146/2015 é o Estatuto da Pessoa com Deficiência."},{"id":2138,"materia":"leg","nivel":0,"enunciado":"A Lei nº 12.850/2013 trata de:","opcoes":["Organizações criminosas","Lavagem de dinheiro","Crimes hediondos","Abuso de autoridade"],"explicacao":"Define organização criminosa e meios de investigação, como colaboração premiada e infiltração."},{"id":2139,"materia":"leg","nivel":0,"enunciado":"A Lei nº 9.503/1997 é o:","opcoes":["Código de Trânsito Brasileiro","Estatuto do Desarmamento","Código de Defesa do Consumidor","Estatuto da Cidade"],"explicacao":"O CTB também define os crimes de trânsito."},{"id":2140,"materia":"inf","nivel":0,"enunciado":"Nos navegadores, como Chrome e Edge, Ctrl + F serve para:","opcoes":["Localizar uma palavra na página","Fechar a aba atual","Favoritar a página","Abrir a tela cheia"],"explicacao":"F de find. No Word em português, localizar é Ctrl+L."},{"id":2141,"materia":"inf","nivel":0,"enunciado":"O que é um pen drive?","opcoes":["Um dispositivo portátil de armazenamento","Um tipo de vírus","Um programa de edição de texto","Uma impressora"],"explicacao":"Ele se conecta pela porta USB."},{"id":2142,"materia":"inf","nivel":0,"enunciado":"A tecla Caps Lock serve para:","opcoes":["Ativar e desativar letras maiúsculas","Apagar o texto","Bloquear o computador","Abrir o menu Iniciar"],"explicacao":"Com ela ativada, as letras saem em maiúsculo."},{"id":2143,"materia":"rl","nivel":0,"enunciado":"Quanto é 15% de 60?","opcoes":["9","15","6","12"],"explicacao":"10% de 60 é 6 e 5% é 3. Somando, 9."},{"id":2144,"materia":"rl","nivel":0,"enunciado":"Qual o próximo número da sequência 100, 90, 80, …?","opcoes":["70","60","75","90"],"explicacao":"A sequência diminui 10 a cada termo."},{"id":2145,"materia":"rl","nivel":0,"enunciado":"Quantos minutos há em 2,5 horas?","opcoes":["150","125","250","90"],"explicacao":"2,5 × 60 = 150."},{"id":2146,"materia":"dh","nivel":0,"enunciado":"Segundo a Constituição, a manifestação do pensamento é livre, mas é vedado:","opcoes":["O anonimato","O uso da internet","A crítica ao governo","A publicação em jornais"],"explicacao":"Art. 5º, IV."},{"id":2147,"materia":"dh","nivel":0,"enunciado":"Segundo a Constituição, a liberdade de consciência e de crença é:","opcoes":["Inviolável","Permitida só para religiões registradas","Restrita a cultos em templos","Dependente de autorização"],"explicacao":"Art. 5º, VI."},{"id":2148,"materia":"dh","nivel":0,"enunciado":"Segundo o art. 227 da Constituição, assegurar com absoluta prioridade os direitos da criança é dever:","opcoes":["Da família, da sociedade e do Estado","Apenas dos pais ou responsáveis","Apenas do Estado, por meio do ECA","Apenas da escola e do Conselho Tutelar"],"explicacao":"É o princípio da proteção integral."},{"id":2149,"materia":"port","nivel":0,"enunciado":"Qual destas palavras é um substantivo?","opcoes":["Coragem","Corajoso","Corajosamente","Encorajar"],"explicacao":"Corajoso é adjetivo, corajosamente é advérbio e encorajar é verbo."},{"id":2150,"materia":"port","nivel":0,"enunciado":"Qual frase está pontuada corretamente?","opcoes":["Maria, venha aqui.","Maria venha, aqui.","Maria venha aqui,","Maria venha aqui."],"explicacao":"O vocativo, termo usado para chamar alguém, fica separado por vírgula."},{"id":2151,"materia":"port","nivel":0,"enunciado":"Qual é um sinônimo de “perspicaz”?","opcoes":["Sagaz","Lento","Ingênuo","Distraído"],"explicacao":"Perspicaz é quem percebe as coisas com rapidez e agudeza."},{"id":2152,"materia":"const","nivel":0,"enunciado":"Qual é a lei máxima do Brasil?","opcoes":["A Constituição Federal","O Código Penal","O Código Civil","A CLT"],"explicacao":"Todas as outras normas devem estar de acordo com ela."},{"id":2153,"materia":"const","nivel":0,"enunciado":"Os estados se organizam e se regem pelas:","opcoes":["Constituições estaduais","Leis orgânicas municipais","Medidas provisórias","Resoluções do Senado"],"explicacao":"Art. 25, observados os princípios da Constituição Federal."},{"id":2154,"materia":"const","nivel":0,"enunciado":"Qual é a forma de governo do Brasil?","opcoes":["República","Monarquia","Federação","Parlamentarismo"],"explicacao":"Federação é a forma de Estado e presidencialismo é o sistema de governo."},{"id":2155,"materia":"adm","nivel":0,"enunciado":"O princípio da moralidade exige que o agente público atue com:","opcoes":["Ética e honestidade","Rapidez acima de tudo","Sigilo total","Preferência pelos amigos"],"explicacao":"Não basta ser legal; o ato precisa ser honesto e de boa-fé."},{"id":2156,"materia":"adm","nivel":0,"enunciado":"Quem é considerado agente público?","opcoes":["Quem exerce função pública, mesmo transitória ou sem remuneração","Apenas quem foi aprovado em concurso público","Apenas os políticos eleitos pelo voto popular","Apenas os servidores federais efetivos"],"explicacao":"O conceito é amplo: inclui servidores, agentes políticos e particulares em colaboração."},{"id":2157,"materia":"adm","nivel":0,"enunciado":"Qual destas é uma EMPRESA PÚBLICA federal?","opcoes":["Caixa Econômica Federal","Banco do Brasil","Petrobras","INSS"],"explicacao":"Banco do Brasil e Petrobras são sociedades de economia mista; o INSS é autarquia."},{"id":2158,"materia":"pen","nivel":0,"enunciado":"Abandonar pessoa que está sob seu cuidado e é incapaz de se defender dos riscos é crime de:","opcoes":["Abandono de incapaz","Omissão de socorro","Maus-tratos","Lesão corporal"],"explicacao":"Art. 133 do Código Penal."},{"id":2159,"materia":"pen","nivel":0,"enunciado":"Quem mata em legítima defesa real:","opcoes":["Não comete crime, pois a ilicitude é excluída","Comete homicídio culposo","Comete homicídio privilegiado","Responde por homicídio simples"],"explicacao":"Art. 23, II, e art. 25 do CP."},{"id":2160,"materia":"pen","nivel":0,"enunciado":"O crime cometido por descuido, sem intenção, é chamado de:","opcoes":["Culposo","Doloso","Preterdoloso, sempre","Tentado"],"explicacao":"Ocorre por imprudência, negligência ou imperícia."},{"id":2161,"materia":"ppen","nivel":0,"enunciado":"No processo penal, o termo “réu” designa:","opcoes":["O acusado","A vítima","A testemunha","O juiz"],"explicacao":"Antes da ação, na fase de investigação, a pessoa é chamada de investigado ou indiciado."},{"id":2162,"materia":"ppen","nivel":0,"enunciado":"Quem expede o mandado de prisão?","opcoes":["A autoridade judiciária","O delegado","O promotor","O policial militar"],"explicacao":"Fora do flagrante, a prisão exige ordem escrita e fundamentada do juiz."},{"id":2163,"materia":"ppen","nivel":0,"enunciado":"A testemunha que mente em juízo pode responder pelo crime de:","opcoes":["Falso testemunho","Denunciação caluniosa","Calúnia","Fraude processual"],"explicacao":"Art. 342 do Código Penal."},{"id":2164,"materia":"leg","nivel":0,"enunciado":"A Lei nº 8.137/1990 trata dos crimes contra:","opcoes":["A ordem tributária","A vida","O meio ambiente","A administração da justiça"],"explicacao":"Também trata de crimes contra a ordem econômica e as relações de consumo."},{"id":2165,"materia":"leg","nivel":0,"enunciado":"Qual lei institui o Estatuto da Pessoa com Deficiência?","opcoes":["Lei nº 13.146/2015","Lei nº 10.741/2003","Lei nº 8.069/1990","Lei nº 12.288/2010"],"explicacao":"É também chamada de Lei Brasileira de Inclusão."},{"id":2166,"materia":"leg","nivel":0,"enunciado":"O Conselho Tutelar é previsto no:","opcoes":["Estatuto da Criança e do Adolescente","Código Penal","Estatuto da Pessoa Idosa","Código de Trânsito"],"explicacao":"Arts. 131 e seguintes do ECA."},{"id":2167,"materia":"inf","nivel":0,"enunciado":"No Windows, o atalho Alt + Tab serve para:","opcoes":["Alternar entre as janelas abertas","Fechar o programa","Abrir o menu Iniciar","Desligar o computador"],"explicacao":"Segurando Alt e tocando Tab, você percorre as janelas."},{"id":2168,"materia":"inf","nivel":0,"enunciado":"Qual destes é um programa de planilha?","opcoes":["Excel","Word","PowerPoint","Paint"],"explicacao":"Word edita textos, PowerPoint faz apresentações e Paint edita imagens."},{"id":2169,"materia":"inf","nivel":0,"enunciado":"O e-mail é um serviço de:","opcoes":["Correio eletrônico","Armazenamento de vídeos","Edição de fotos","Planilhas"],"explicacao":"Ele permite enviar mensagens e anexos pela internet."},{"id":2170,"materia":"rl","nivel":0,"enunciado":"Quanto é 2/5 de 50?","opcoes":["20","10","25","30"],"explicacao":"50 ÷ 5 = 10; 10 × 2 = 20."},{"id":2171,"materia":"rl","nivel":0,"enunciado":"Qual a próxima letra da sequência A, C, E, G, …?","opcoes":["I","H","J","K"],"explicacao":"A sequência pula uma letra a cada passo."},{"id":2172,"materia":"rl","nivel":0,"enunciado":"Quanto é 3² + 4²?","opcoes":["25","49","14","7"],"explicacao":"9 + 16 = 25."},{"id":2173,"materia":"dh","nivel":0,"enunciado":"O sistema interamericano de direitos humanos pertence à:","opcoes":["OEA","ONU","OTAN","União Europeia"],"explicacao":"Seus órgãos principais são a Comissão e a Corte Interamericanas."},{"id":2174,"materia":"dh","nivel":0,"enunciado":"Segundo a Constituição, o exercício de qualquer trabalho, ofício ou profissão é:","opcoes":["Livre, atendidas as qualificações que a lei estabelecer","Proibido sem autorização do governo","Restrito a brasileiros natos","Livre apenas para concursados"],"explicacao":"Art. 5º, XIII."},{"id":2175,"materia":"dh","nivel":0,"enunciado":"Segundo o art. 205 da Constituição, a educação é:","opcoes":["Direito de todos e dever do Estado e da família","Dever exclusivo da escola e dos professores","Direito apenas de crianças e adolescentes","Opcional para o Estado, conforme o orçamento"],"explicacao":"Ela visa ao pleno desenvolvimento da pessoa e ao preparo para a cidadania."},{"id":2176,"materia":"port","nivel":0,"enunciado":"Em qual palavra há um dígrafo?","opcoes":["Chuva","Prova","Livro","Blusa"],"explicacao":"Em “chuva”, as letras CH representam um único som. Em “pr”, “vr” e “bl” há encontro consonantal."},{"id":2177,"materia":"port","nivel":0,"enunciado":"Qual é o plural de “animal”?","opcoes":["Animais","Animales","Animals","Animaus"],"explicacao":"Palavras terminadas em -al trocam o L por -is: animal, animais."},{"id":2178,"materia":"port","nivel":0,"enunciado":"Qual destas palavras é um verbo?","opcoes":["Estudar","Estudante","Estudioso","Estudantil"],"explicacao":"Estudante é substantivo, estudioso e estudantil são adjetivos."},{"id":2179,"materia":"const","nivel":0,"enunciado":"No âmbito federal, quem elabora as leis?","opcoes":["O Congresso Nacional","O Presidente da República","O STF","Os ministérios"],"explicacao":"É a função típica do Poder Legislativo."},{"id":2180,"materia":"const","nivel":0,"enunciado":"Os municípios, segundo a Constituição, são:","opcoes":["Entes federativos com autonomia","Subordinados aos estados","Órgãos da União","Regiões administrativas sem autonomia"],"explicacao":"Art. 18: União, estados, DF e municípios são autônomos."},{"id":2181,"materia":"const","nivel":0,"enunciado":"Os vereadores integram a:","opcoes":["Câmara Municipal","Assembleia Legislativa","Câmara dos Deputados","Prefeitura"],"explicacao":"É o Poder Legislativo do município."},{"id":2182,"materia":"adm","nivel":0,"enunciado":"Pela Lei nº 8.112/1990, o servidor deve tratar as pessoas com:","opcoes":["Urbanidade","Indiferença","Preferência pelos conhecidos","Rigor excessivo"],"explicacao":"Art. 116, XI."},{"id":2183,"materia":"adm","nivel":0,"enunciado":"Quem chefia a Administração Pública federal direta?","opcoes":["O Presidente da República","O Presidente do Senado","O Presidente do STF","O Procurador-Geral da República"],"explicacao":"Art. 84, II, da Constituição."},{"id":2184,"materia":"adm","nivel":0,"enunciado":"Ato administrativo vinculado é aquele em que:","opcoes":["A lei não deixa margem de escolha ao administrador","O administrador escolhe livremente","Não há lei aplicável","O particular decide"],"explicacao":"Preenchidos os requisitos, a Administração deve praticá-lo."},{"id":2185,"materia":"pen","nivel":0,"enunciado":"Participar de briga envolvendo três ou mais pessoas, com agressões recíprocas, é crime de:","opcoes":["Rixa","Lesão corporal","Ameaça","Vias de fato"],"explicacao":"Art. 137 do CP."},{"id":2186,"materia":"pen","nivel":0,"enunciado":"Constranger alguém, com violência ou grave ameaça, a não fazer o que a lei permite é crime de:","opcoes":["Constrangimento ilegal","Ameaça","Extorsão","Sequestro"],"explicacao":"Art. 146 do Código Penal."},{"id":2187,"materia":"pen","nivel":0,"enunciado":"Praticar ato obsceno em lugar público é crime previsto no:","opcoes":["Código Penal","Código Civil","ECA apenas","Código de Trânsito"],"explicacao":"Art. 233 do CP."},{"id":2188,"materia":"ppen","nivel":0,"enunciado":"Concluído o inquérito policial, a autoridade policial remete os autos ao:","opcoes":["Juiz competente","Governador","Delegado-geral apenas","Defensor público"],"explicacao":"Art. 10, § 1º, do CPP."},{"id":2189,"materia":"ppen","nivel":0,"enunciado":"Segundo o CPP, quem pode ser testemunha?","opcoes":["Toda pessoa","Apenas maiores de 21 anos","Apenas servidores públicos","Apenas parentes da vítima"],"explicacao":"Art. 202 do CPP."},{"id":2190,"materia":"ppen","nivel":0,"enunciado":"O cargo de delegado de polícia é privativo de bacharel em:","opcoes":["Direito","Administração","Segurança Pública","Qualquer curso superior"],"explicacao":"Art. 3º da Lei 12.830/2013."},{"id":2191,"materia":"leg","nivel":0,"enunciado":"A Lei Maria da Penha recebeu esse nome em homenagem a:","opcoes":["Uma mulher que sofreu violência doméstica","Uma ministra do STF autora do voto","Uma deputada que relatou o projeto","Uma delegada pioneira da Bahia"],"explicacao":"Maria da Penha Maia Fernandes ficou paraplégica após agressão do então marido e levou o caso a instâncias internacionais."},{"id":2192,"materia":"leg","nivel":0,"enunciado":"No Código de Trânsito, o órgão máximo normativo e consultivo do Sistema Nacional de Trânsito é o:","opcoes":["CONTRAN","DETRAN","DNIT","PRF"],"explicacao":"Art. 7º, I, do CTB."},{"id":2193,"materia":"leg","nivel":0,"enunciado":"A Lei nº 9.605/1998 trata dos crimes:","opcoes":["Ambientais","Tributários","De trânsito","Hediondos"],"explicacao":"É a Lei de Crimes Ambientais."},{"id":2194,"materia":"inf","nivel":0,"enunciado":"No navegador, a tecla F5 serve para:","opcoes":["Atualizar a página","Fechar a aba","Abrir o histórico","Imprimir"],"explicacao":"Recarrega a página atual."},{"id":2195,"materia":"inf","nivel":0,"enunciado":"Wi-Fi é uma tecnologia de:","opcoes":["Rede sem fio","Impressão","Armazenamento em disco","Edição de vídeo"],"explicacao":"Conecta dispositivos à rede por ondas de rádio."},{"id":2196,"materia":"inf","nivel":0,"enunciado":"No Explorador de Arquivos do Windows, o atalho Ctrl + A serve para:","opcoes":["Selecionar todos os itens","Atualizar a pasta","Apagar os arquivos","Renomear o arquivo"],"explicacao":"Pegadinha clássica: no Word e no Excel em português, Ctrl+A abre um arquivo e Ctrl+T seleciona tudo."},{"id":2197,"materia":"rl","nivel":0,"enunciado":"Quanto é 7 × 8?","opcoes":["56","54","48","64"],"explicacao":"Tabuada do 7: 7 × 8 = 56."},{"id":2198,"materia":"rl","nivel":0,"enunciado":"Qual o próximo número da sequência 2, 5, 8, 11, …?","opcoes":["14","13","15","12"],"explicacao":"Soma 3 a cada termo."},{"id":2199,"materia":"rl","nivel":0,"enunciado":"Quanto é a metade de 3/4?","opcoes":["3/8","3/2","6/4","1/4"],"explicacao":"Metade é multiplicar por 1/2: 3/4 × 1/2 = 3/8."},{"id":2200,"materia":"dh","nivel":0,"enunciado":"Segundo o art. 196 da Constituição, a saúde é:","opcoes":["Direito de todos e dever do Estado","Serviço apenas privado","Direito só de trabalhadores","Responsabilidade só da família"],"explicacao":"Garantida por políticas sociais e econômicas e acesso universal e igualitário."},{"id":2201,"materia":"dh","nivel":0,"enunciado":"Em tempo de paz, a locomoção no território nacional é:","opcoes":["Livre, nos termos da lei","Proibida sem autorização","Restrita a brasileiros natos","Livre só durante o dia"],"explicacao":"Art. 5º, XV."},{"id":2202,"materia":"dh","nivel":0,"enunciado":"A Constituição assegura a todos o acesso à:","opcoes":["Informação, resguardado o sigilo da fonte","Ficha criminal de qualquer pessoa","Senha bancária de terceiros mediante pedido","Correspondência alheia em caso de interesse"],"explicacao":"Art. 5º, XIV."},{"id":2203,"materia":"est","nivel":0,"enunciado":"Qual a média aritmética de 4, 6 e 8?","opcoes":["6","5","7","18"],"explicacao":"(4 + 6 + 8) ÷ 3 = 18 ÷ 3 = 6."},{"id":2204,"materia":"est","nivel":0,"enunciado":"Qual a moda do conjunto 2, 3, 3, 5, 7?","opcoes":["3","2","5","4"],"explicacao":"Moda é o valor que mais se repete: o 3 aparece duas vezes."},{"id":2205,"materia":"est","nivel":0,"enunciado":"Qual a mediana de 1, 3, 5, 7, 9?","opcoes":["5","3","7","25"],"explicacao":"Com os dados em ordem, a mediana é o valor do meio. Aqui, o 5."},{"id":2206,"materia":"est","nivel":0,"enunciado":"Em estatística, a moda é o valor que:","opcoes":["Aparece com mais frequência","Fica no centro dos dados ordenados","Resulta da soma dividida pelo total","Separa os 25% menores valores"],"explicacao":"O centro dos dados ordenados é a mediana; a soma dividida pelo total é a média."},{"id":2207,"materia":"est","nivel":0,"enunciado":"A diferença entre o maior e o menor valor de um conjunto é a:","opcoes":["Amplitude","Mediana","Moda","Variância"],"explicacao":"É a medida de dispersão mais simples: máximo menos mínimo."},{"id":2208,"materia":"est","nivel":0,"enunciado":"O conjunto de todos os elementos que se deseja estudar chama-se:","opcoes":["População","Amostra","Variável","Frequência"],"explicacao":"Amostra é só uma parte da população."},{"id":2209,"materia":"est","nivel":0,"enunciado":"Uma parte da população, selecionada para estudo, chama-se:","opcoes":["Amostra","Censo","Parâmetro","Rol"],"explicacao":"Estuda-se a amostra para tirar conclusões sobre a população."},{"id":2210,"materia":"est","nivel":0,"enunciado":"A pesquisa que coleta dados de todos os elementos da população é o:","opcoes":["Censo","Rol","Histograma","Quartil"],"explicacao":"No censo não há amostragem: todos são pesquisados, como no Censo do IBGE."},{"id":2211,"materia":"est","nivel":0,"enunciado":"“Cor dos olhos” é uma variável:","opcoes":["Qualitativa","Quantitativa discreta","Quantitativa contínua","Numérica"],"explicacao":"Expressa uma qualidade, não um número. É qualitativa nominal."},{"id":2212,"materia":"est","nivel":0,"enunciado":"“Número de filhos” é uma variável quantitativa:","opcoes":["Discreta","Contínua","Nominal","Ordinal"],"explicacao":"Assume valores inteiros que se contam: 0, 1, 2…"},{"id":2213,"materia":"est","nivel":0,"enunciado":"“Altura de uma pessoa” é uma variável quantitativa:","opcoes":["Contínua","Discreta","Nominal","Ordinal"],"explicacao":"Pode assumir qualquer valor num intervalo, como 1,734 m. Variáveis que se medem costumam ser contínuas."},{"id":2214,"materia":"est","nivel":0,"enunciado":"Qual gráfico é mais usado para mostrar partes de um todo em porcentagem?","opcoes":["Gráfico de setores","Gráfico de linhas","Histograma","Diagrama de dispersão"],"explicacao":"É o gráfico de pizza: cada fatia é uma parte do total."},{"id":2215,"materia":"est","nivel":0,"enunciado":"Numa turma de 40 alunos, 10 são canhotos. Qual a frequência relativa de canhotos?","opcoes":["25%","10%","40%","4%"],"explicacao":"Frequência relativa = 10 ÷ 40 = 0,25 = 25%."},{"id":2216,"materia":"est","nivel":0,"enunciado":"Qual a média de 10, 20, 30 e 40?","opcoes":["25","20","30","100"],"explicacao":"(10 + 20 + 30 + 40) ÷ 4 = 100 ÷ 4 = 25."},{"id":2217,"materia":"est","nivel":0,"enunciado":"Qual a moda de 1, 2, 2, 3, 3, 3, 4?","opcoes":["3","2","4","7"],"explicacao":"O 3 aparece três vezes, mais que qualquer outro valor."},{"id":2218,"materia":"est","nivel":0,"enunciado":"Qual a amplitude do conjunto 3, 8, 12, 20?","opcoes":["17","20","9","23"],"explicacao":"Máximo menos mínimo: 20 − 3 = 17."},{"id":2219,"materia":"est","nivel":0,"enunciado":"Os dados organizados em ordem crescente ou decrescente formam um:","opcoes":["Rol","Censo","Histograma","Parâmetro"],"explicacao":"O rol é o primeiro passo para achar a mediana e os quartis."},{"id":2220,"materia":"est","nivel":0,"enunciado":"Um conjunto com dois valores que mais se repetem, com a mesma frequência, é:","opcoes":["Bimodal","Amodal","Unimodal","Simétrico"],"explicacao":"Tem duas modas. Ex.: 1, 1, 2, 3, 3."},{"id":2221,"materia":"est","nivel":0,"enunciado":"Um conjunto em que nenhum valor se repete é:","opcoes":["Amodal","Bimodal","Unimodal","Multimodal"],"explicacao":"Sem repetição, não há moda."},{"id":2222,"materia":"est","nivel":0,"enunciado":"Qual a mediana de 2, 4, 6, 8?","opcoes":["5","4","6","20"],"explicacao":"Com quantidade par, a mediana é a média dos dois centrais: (4 + 6) ÷ 2 = 5."},{"id":2223,"materia":"est","nivel":0,"enunciado":"O número de vezes que um valor aparece num conjunto é a sua frequência:","opcoes":["Absoluta","Relativa","Acumulada","Percentual"],"explicacao":"A relativa é essa contagem dividida pelo total."},{"id":2224,"materia":"cont","nivel":0,"enunciado":"O conjunto de bens, direitos e obrigações de uma entidade é o:","opcoes":["Patrimônio","Capital social","Lucro","Balancete"],"explicacao":"É o objeto de estudo da contabilidade."},{"id":2225,"materia":"cont","nivel":0,"enunciado":"Dinheiro em caixa, veículos e estoques são exemplos de:","opcoes":["Bens","Obrigações","Receitas","Despesas"],"explicacao":"Bens são itens que a entidade possui e que podem ser avaliados em dinheiro."},{"id":2226,"materia":"cont","nivel":0,"enunciado":"Valores a receber de clientes, como duplicatas a receber, são:","opcoes":["Direitos","Obrigações","Despesas","Receitas"],"explicacao":"São créditos da empresa contra terceiros."},{"id":2227,"materia":"cont","nivel":0,"enunciado":"Salários a pagar e fornecedores são exemplos de:","opcoes":["Obrigações","Direitos","Bens","Receitas"],"explicacao":"São dívidas com terceiros e ficam no passivo."},{"id":2228,"materia":"cont","nivel":0,"enunciado":"O ativo é formado por:","opcoes":["Bens e direitos","Obrigações e capital","Receitas e despesas","Apenas dinheiro"],"explicacao":"As obrigações ficam no passivo."},{"id":2229,"materia":"cont","nivel":0,"enunciado":"O passivo exigível representa:","opcoes":["As obrigações com terceiros","Os bens da empresa","Os direitos a receber","As receitas do período"],"explicacao":"É o capital de terceiros. O patrimônio líquido é o capital próprio."},{"id":2230,"materia":"cont","nivel":0,"enunciado":"Qual a equação fundamental da contabilidade?","opcoes":["Ativo = Passivo + PL","Ativo = Passivo − PL","PL = Ativo + Passivo","Passivo = Ativo + PL"],"explicacao":"O que a empresa tem (ativo) é financiado por terceiros (passivo) ou pelos sócios (PL)."},{"id":2231,"materia":"cont","nivel":0,"enunciado":"Uma empresa tem ativo de R$ 100 mil e passivo de R$ 60 mil. Qual o patrimônio líquido?","opcoes":["R$ 40 mil","R$ 160 mil","R$ 60 mil","R$ 100 mil"],"explicacao":"PL = Ativo − Passivo = 100 − 60 = 40 mil."},{"id":2232,"materia":"cont","nivel":0,"enunciado":"A conta “Caixa” pertence ao:","opcoes":["Ativo","Passivo","Patrimônio líquido","Resultado"],"explicacao":"Fica no ativo circulante, no grupo das disponibilidades."},{"id":2233,"materia":"cont","nivel":0,"enunciado":"A conta “Fornecedores” pertence ao:","opcoes":["Passivo","Ativo","Patrimônio líquido","Resultado"],"explicacao":"Representa compras feitas a prazo, ainda não pagas."},{"id":2234,"materia":"cont","nivel":0,"enunciado":"A conta “Capital Social” pertence ao:","opcoes":["Patrimônio líquido","Ativo circulante","Passivo circulante","Resultado"],"explicacao":"É o valor investido pelos sócios."},{"id":2235,"materia":"cont","nivel":0,"enunciado":"Receitas e despesas são contas:","opcoes":["De resultado","Do ativo","Do passivo","De compensação"],"explicacao":"São encerradas no fim do período para apurar o lucro ou prejuízo."},{"id":2236,"materia":"cont","nivel":0,"enunciado":"Uma conta do ativo aumenta com lançamento a:","opcoes":["Débito","Crédito","Estorno","Saldo"],"explicacao":"Contas de ativo e de despesa têm natureza devedora."},{"id":2237,"materia":"cont","nivel":0,"enunciado":"Uma conta do passivo aumenta com lançamento a:","opcoes":["Crédito","Débito","Estorno","Saldo"],"explicacao":"Contas de passivo, PL e receita têm natureza credora."},{"id":2238,"materia":"cont","nivel":0,"enunciado":"O método em que todo débito corresponde a um crédito de igual valor é o das:","opcoes":["Partidas dobradas","Partidas simples","Contas correntes","Médias ponderadas"],"explicacao":"Criado por Luca Pacioli, é a base da escrituração contábil."},{"id":2239,"materia":"cont","nivel":0,"enunciado":"Salários do mês, aluguel e energia elétrica são exemplos de:","opcoes":["Despesas","Receitas","Ativos","Passivos"],"explicacao":"Despesas reduzem o resultado e, por consequência, o patrimônio líquido."},{"id":2240,"materia":"cont","nivel":0,"enunciado":"A venda de mercadorias gera para a empresa uma:","opcoes":["Receita","Despesa","Obrigação","Depreciação"],"explicacao":"A receita aumenta o resultado do período."},{"id":2241,"materia":"cont","nivel":0,"enunciado":"O livro em que se registram as operações em ordem cronológica é o:","opcoes":["Diário","Razão","Caixa","Inventário"],"explicacao":"O Livro Diário é obrigatório pela legislação comercial."},{"id":2242,"materia":"cont","nivel":0,"enunciado":"O livro que reúne os lançamentos separados por conta é o:","opcoes":["Razão","Diário","Ponto","Inventário"],"explicacao":"Mostra a movimentação e o saldo de cada conta."},{"id":2243,"materia":"cont","nivel":0,"enunciado":"Ativo maior que o passivo exigível indica situação líquida:","opcoes":["Positiva","Negativa","Nula","Inexistente"],"explicacao":"Significa patrimônio líquido positivo."},{"id":2244,"materia":"cont","nivel":0,"enunciado":"Quando o passivo exigível é maior que o ativo, há:","opcoes":["Passivo a descoberto","Lucro acumulado","Situação líquida positiva","Capital próprio elevado"],"explicacao":"O patrimônio líquido fica negativo."},{"id":2245,"materia":"port","nivel":0,"enunciado":"Qual é o plural de “cão”?","opcoes":["Cães","Cãos","Cões","Cãoes"],"explicacao":"“Cão” faz o plural em -ães, como “pães” e “capitães”."},{"id":2246,"materia":"port","nivel":0,"enunciado":"Qual é o antônimo de “honesto”?","opcoes":["Desonesto","Íntegro","Correto","Sincero"],"explicacao":"Íntegro, correto e sincero são sinônimos de honesto."},{"id":2247,"materia":"port","nivel":0,"enunciado":"Qual é um sinônimo de “veloz”?","opcoes":["Rápido","Lento","Pesado","Calmo"],"explicacao":"Veloz é o que se move com rapidez."},{"id":2248,"materia":"port","nivel":0,"enunciado":"Qual é a grafia correta?","opcoes":["Excesso","Esceso","Exceço","Ecesso"],"explicacao":"Escreve-se com XC e SS: excesso."},{"id":2249,"materia":"port","nivel":0,"enunciado":"Qual é o feminino de “ator”?","opcoes":["Atriz","Atora","Atoa","Atriza"],"explicacao":"Como imperador e imperatriz."},{"id":2250,"materia":"port","nivel":0,"enunciado":"Qual é o coletivo de abelhas?","opcoes":["Enxame","Cardume","Rebanho","Alcateia"],"explicacao":"Cardume é de peixes, rebanho de gado e alcateia de lobos."},{"id":2251,"materia":"port","nivel":0,"enunciado":"Qual destas palavras é paroxítona?","opcoes":["Livro","Café","Médico","Avó"],"explicacao":"Na paroxítona, a penúltima sílaba é a tônica: LI-vro."},{"id":2252,"materia":"port","nivel":0,"enunciado":"Qual frase está de acordo com a norma-padrão?","opcoes":["Nós vamos ao cinema.","Nós vai ao cinema.","A gente vamos ao cinema.","Nós vai no cinema."],"explicacao":"“Nós” pede o verbo na 1ª pessoa do plural; “a gente” pede a 3ª do singular (a gente vai)."},{"id":2253,"materia":"port","nivel":0,"enunciado":"Qual é a grafia correta?","opcoes":["Cansaço","Cansasso","Cançaço","Canssaço"],"explicacao":"Cansaço: S depois de N e Ç antes de A."},{"id":2254,"materia":"port","nivel":0,"enunciado":"Quantas sílabas tem a palavra “polícia”?","opcoes":["4","3","5","2"],"explicacao":"Po-lí-ci-a. O “ia” final forma hiato."},{"id":2255,"materia":"const","nivel":0,"enunciado":"Quem elege o Presidente da República?","opcoes":["O povo, pelo voto direto","O Congresso Nacional","O Supremo Tribunal Federal","Os governadores dos estados"],"explicacao":"A eleição é direta, por maioria absoluta dos votos válidos."},{"id":2256,"materia":"const","nivel":0,"enunciado":"Qual é a duração do mandato de um vereador?","opcoes":["4 anos","2 anos","6 anos","8 anos"],"explicacao":"Igual ao do prefeito."},{"id":2257,"materia":"const","nivel":0,"enunciado":"Quem chefia o Poder Executivo municipal?","opcoes":["O Prefeito","O Vereador","O Governador","O Juiz de direito"],"explicacao":"Os vereadores formam o Legislativo do município."},{"id":2258,"materia":"const","nivel":0,"enunciado":"O Senado Federal é composto de representantes:","opcoes":["Dos estados e do DF","Do povo","Dos municípios","Dos partidos"],"explicacao":"Art. 46. Os representantes do povo estão na Câmara dos Deputados."},{"id":2259,"materia":"const","nivel":0,"enunciado":"Segundo a Constituição, a casa é:","opcoes":["Asilo inviolável do indivíduo","Propriedade do Estado","Bem de uso comum do povo","Local de livre acesso policial"],"explicacao":"Art. 5º, XI, com as exceções que a própria Constituição prevê."},{"id":2260,"materia":"const","nivel":0,"enunciado":"A Constituição de 1988 ficou conhecida como:","opcoes":["Constituição Cidadã","Constituição Polaca","Constituição Imperial","Carta Outorgada"],"explicacao":"O nome foi dado por Ulysses Guimarães, pela ampliação de direitos. A Polaca é a de 1937."},{"id":2261,"materia":"const","nivel":0,"enunciado":"Os deputados estaduais integram a:","opcoes":["Assembleia Legislativa","Câmara Municipal","Câmara dos Deputados","Senado Federal"],"explicacao":"É o Poder Legislativo do estado."},{"id":2262,"materia":"const","nivel":0,"enunciado":"Qual tribunal é o guardião da Constituição Federal?","opcoes":["O STF","O STJ","O TSE","O TST"],"explicacao":"Art. 102 da Constituição."},{"id":2263,"materia":"const","nivel":0,"enunciado":"Qual a idade mínima para votar no Brasil?","opcoes":["16 anos","18 anos","14 anos","21 anos"],"explicacao":"Dos 16 aos 18 anos o voto é facultativo; a partir dos 18, é obrigatório."},{"id":2264,"materia":"const","nivel":0,"enunciado":"Os direitos e deveres individuais e coletivos estão principalmente no art.:","opcoes":["5º","1º","37","144"],"explicacao":"O art. 5º é o mais cobrado em concursos."},{"id":2265,"materia":"adm","nivel":0,"enunciado":"No LIMPE do art. 37, o “P” significa:","opcoes":["Publicidade","Proporcionalidade","Probidade","Prudência"],"explicacao":"Legalidade, Impessoalidade, Moralidade, Publicidade e Eficiência."},{"id":2266,"materia":"adm","nivel":0,"enunciado":"No LIMPE do art. 37, o “E” significa:","opcoes":["Eficiência","Economia","Equidade","Ética"],"explicacao":"Foi incluído pela EC 19/1998."},{"id":2267,"materia":"adm","nivel":0,"enunciado":"Ministérios e secretarias são órgãos da administração:","opcoes":["Direta","Indireta","Privada","Terceirizada"],"explicacao":"A indireta reúne autarquias, fundações, empresas públicas e sociedades de economia mista."},{"id":2268,"materia":"adm","nivel":0,"enunciado":"As fundações públicas pertencem à administração:","opcoes":["Indireta","Direta","Privada","Legislativa"],"explicacao":"Têm personalidade jurídica própria."},{"id":2269,"materia":"adm","nivel":0,"enunciado":"A Constituição permite a greve de servidores públicos civis?","opcoes":["Sim, nos termos de lei específica","Não, em nenhum caso","Sim, sem qualquer limite","Apenas para os militares"],"explicacao":"Art. 37, VII. Para os militares, a greve é proibida."},{"id":2270,"materia":"adm","nivel":0,"enunciado":"A obrigação de tornar públicos os atos da Administração decorre do princípio da:","opcoes":["Publicidade","Legalidade","Eficiência","Impessoalidade"],"explicacao":"O sigilo é exceção, nos casos previstos em lei."},{"id":2271,"materia":"adm","nivel":0,"enunciado":"A Empresa Brasileira de Correios e Telégrafos é exemplo de:","opcoes":["Empresa pública","Autarquia","Sociedade de economia mista","Órgão de ministério"],"explicacao":"Seu capital é integralmente da União."},{"id":2272,"materia":"adm","nivel":0,"enunciado":"O Ibama é exemplo de:","opcoes":["Autarquia","Empresa pública","Sociedade de economia mista","Fundação privada"],"explicacao":"É uma autarquia federal ligada à área ambiental."},{"id":2273,"materia":"adm","nivel":0,"enunciado":"A remuneração dos servidores públicos só pode ser fixada ou alterada por:","opcoes":["Lei específica","Decreto do chefe","Portaria do ministro","Contrato individual"],"explicacao":"Art. 37, X, da Constituição."},{"id":2274,"materia":"adm","nivel":0,"enunciado":"Os cargos públicos são acessíveis a:","opcoes":["Brasileiros e, na forma da lei, estrangeiros","Apenas brasileiros natos e naturalizados","Apenas eleitores em dia com a Justiça","Apenas pessoas com curso superior"],"explicacao":"Art. 37, I, da Constituição."},{"id":2275,"materia":"pen","nivel":0,"enunciado":"Matar alguém sem intenção, por imprudência, é homicídio:","opcoes":["Culposo","Doloso","Qualificado","Privilegiado"],"explicacao":"No culposo não há intenção; há imprudência, negligência ou imperícia."},{"id":2276,"materia":"pen","nivel":0,"enunciado":"Quem ajuda ou instiga o crime, sem praticar a conduta principal, é o:","opcoes":["Partícipe","Coautor","Vítima","Testemunha"],"explicacao":"O coautor pratica a conduta junto com o autor."},{"id":2277,"materia":"pen","nivel":0,"enunciado":"Pegar o celular de alguém mediante ameaça com faca é crime de:","opcoes":["Roubo","Furto","Estelionato","Receptação"],"explicacao":"Há grave ameaça à pessoa."},{"id":2278,"materia":"pen","nivel":0,"enunciado":"Pegar um objeto de uma loja sem que ninguém perceba, sem violência, é crime de:","opcoes":["Furto","Roubo","Extorsão","Dano"],"explicacao":"Subtração sem violência nem grave ameaça."},{"id":2279,"mate