iado":"Pagar a conta de luz de uma escola pública é uma despesa:","opcoes":["Corrente","De capital","Extraordinária","De investimento"],"explicacao":"Despesa corrente mantém os serviços que já existem."},{"id":2395,"materia":"gest","nivel":0,"enunciado":"Quem coordena uma equipe e orienta o trabalho dela é o:","opcoes":["Líder","Estagiário","Fornecedor","Cliente"],"explicacao":"Liderar é influenciar pessoas para alcançar objetivos."},{"id":2396,"materia":"gest","nivel":0,"enunciado":"Trabalhar em equipe significa:","opcoes":["Unir esforços para um objetivo comum","Fazer tudo sozinho","Competir com os colegas","Evitar falar com os outros"],"explicacao":"Cooperação é a base do trabalho em equipe."},{"id":2397,"materia":"gest","nivel":0,"enunciado":"Atender bem o cidadão em um órgão público é exemplo de foco no:","opcoes":["Usuário do serviço","Lucro da empresa","Concorrente","Fornecedor"],"explicacao":"A administração existe para servir à população."},{"id":2398,"materia":"gest","nivel":0,"enunciado":"Feedback é:","opcoes":["Retorno sobre o desempenho de alguém","Uma punição formal","Um tipo de salário","Um documento de demissão"],"explicacao":"Um bom feedback é claro, respeitoso e ajuda a melhorar."},{"id":2399,"materia":"gest","nivel":0,"enunciado":"Treinar os servidores serve para:","opcoes":["Desenvolver conhecimentos e habilidades","Reduzir o número de servidores","Aumentar a burocracia","Evitar avaliações"],"explicacao":"Capacitação melhora a qualidade do serviço."},{"id":2400,"materia":"gest","nivel":0,"enunciado":"Um indicador de desempenho serve para:","opcoes":["Medir resultados","Contratar pessoas","Pagar fornecedores","Elaborar leis"],"explicacao":"Ex.: tempo médio de atendimento ao cidadão."},{"id":2401,"materia":"gest","nivel":0,"enunciado":"Um conflito no trabalho deve ser tratado, de preferência, com:","opcoes":["Diálogo e negociação","Gritos e ameaças","Silêncio permanente","Demissão imediata"],"explicacao":"Conflitos bem administrados podem gerar melhorias."},{"id":2402,"materia":"gest","nivel":0,"enunciado":"A ética no serviço público exige do servidor:","opcoes":["Honestidade e respeito ao interesse público","Favorecer amigos e parentes","Usar o cargo para ganhos pessoais","Esconder informações públicas"],"explicacao":"O servidor deve agir com moralidade e impessoalidade."},{"id":2403,"materia":"gest","nivel":0,"enunciado":"Um processo de trabalho é:","opcoes":["Uma sequência de atividades que gera um resultado","Um documento judicial","Um tipo de punição","Uma reunião informal"],"explicacao":"Ex.: receber, analisar e responder um pedido do cidadão."},{"id":2404,"materia":"gest","nivel":0,"enunciado":"Planejar significa:","opcoes":["Definir objetivos e como alcançá-los","Corrigir erros já ocorridos","Contratar funcionários","Fiscalizar o trabalho pronto"],"explicacao":"O planejamento é a primeira função administrativa."},{"id":2405,"materia":"arq","nivel":0,"enunciado":"O local onde os documentos são guardados de forma organizada é o:","opcoes":["Arquivo","Almoxarifado","Refeitório","Auditório"],"explicacao":"O arquivo guarda documentos para consulta e prova."},{"id":2406,"materia":"arq","nivel":0,"enunciado":"O profissional especializado em organizar arquivos é o:","opcoes":["Arquivista","Engenheiro","Contador","Nutricionista"],"explicacao":"A profissão é regulamentada pela Lei 6.546/1978."},{"id":2407,"materia":"arq","nivel":0,"enunciado":"Traças e cupins, para os documentos, são:","opcoes":["Agentes de deterioração","Formas de conservação","Métodos de arquivamento","Tipos de documento"],"explicacao":"Insetos destroem o papel e exigem controle de pragas."},{"id":2408,"materia":"arq","nivel":0,"enunciado":"Uma certidão de nascimento em papel é documento de gênero:","opcoes":["Textual","Sonoro","Cartográfico","Filmográfico"],"explicacao":"Documentos escritos são do gênero textual."},{"id":2409,"materia":"arq","nivel":0,"enunciado":"Ao receber um documento, o protocolo registra, entre outros dados:","opcoes":["A data de entrada e o assunto","A cor do papel","O peso do envelope","O tipo de caneta usada"],"explicacao":"O registro permite controlar a tramitação."},{"id":2410,"materia":"arq","nivel":0,"enunciado":"Organizar documentos por números (1, 2, 3...) é o método:","opcoes":["Numérico","Alfabético","Geográfico","Ideográfico"],"explicacao":"O número é dado na ordem de chegada ou por outro critério."},{"id":2411,"materia":"arq","nivel":0,"enunciado":"Um documento de arquivo pode estar em:","opcoes":["Papel, foto, vídeo ou meio digital","Somente papel","Somente meio digital","Apenas livros impressos"],"explicacao":"O que define o arquivo é a origem, não o suporte."},{"id":2412,"materia":"arq","nivel":0,"enunciado":"Eliminar documentos públicos sem autorização é:","opcoes":["Proibido por lei","Permitido a qualquer servidor","Obrigatório a cada ano","Uma boa prática de limpeza"],"explicacao":"A eliminação exige avaliação e autorização da instituição arquivística."},{"id":2413,"materia":"arq","nivel":0,"enunciado":"Guardar documentos longe da luz do sol ajuda a:","opcoes":["Conservá-los por mais tempo","Apagar as informações","Aumentar a umidade","Atrair insetos"],"explicacao":"A luz desbota tintas e enfraquece o papel."},{"id":2414,"materia":"arq","nivel":0,"enunciado":"A Lei de Acesso à Informação é a Lei:","opcoes":["12.527/2011","8.159/1991","13.709/2018","4.320/1964"],"explicacao":"A 13.709/2018 é a LGPD; a 8.159/1991 é a Lei de Arquivos."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select nivel, count(*) as questoes from public.questoes group by nivel order by nivel;
